			layoutBarriers++
		}
		return nil
	})
	reopened, err := treedb.Open(opts)
	if err == nil {
		err = reopened.Close()
	}
	restore()
	if err != nil {
		t.Fatal(err)
	}
	if layoutBarriers != 0 {
		t.Fatalf("proven steady-state layout emitted %d creation barriers, want no rewrite", layoutBarriers)
	}
}

